using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{public static int Run(string folder){var j=new JavaScriptSerializer{MaxJsonLength=64000000};dynamic l=Marshal.GetActiveObject("IronCAD.Application");var a=(IZBaseApp)l.ZIronCADApp;var s=(IZSceneDoc)a.ActiveDoc;var u=(IZSceneDocUtility)s;var r=new List<object>();foreach(int id in new[]{11201,11194,11175}){var p=(IZPartFeatureMgr)u.GetElementById(id);var f=new List<object>();for(int i=0;i<p.GetFeaturesCount();i++){var e=(IZElement)p.GetFeatureAt(i);f.Add(new{id=e.Id,name=e.Name,suppressed=e.GetStateStatus(eZElementState.Z_SUPPRESSED),type=e.Type.ToString(),curves=e is IZExtrudeFeature?((Array)((IZExtrudeFeature)e).CrossSection.GetCurveIds()).Length:0});}double achieved;var part=(IZPart)u.GetElementById(id);var box=(double[])part.GetBody(true).GetBoundingBox();double volume=((IZPartProperty)part).GetVolume(1e-8,out achieved);r.Add(new{id=id,features=f,volume=volume,box=box});}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(new{passed=true,parts=r}));return 0;}}}
